'use strict';
const SORTS={total:['Total solved',u=>u.total||0],easy:['Easy solved',u=>u.easy||0],medium:['Medium solved',u=>u.medium||0],hard:['Hard solved',u=>u.hard||0],rating:['Contest rating',u=>u.rating||0],today:['Solved today',u=>u.today||0],week:['Last 7 days',u=>u.week||0],month:['Last 30 days',u=>u.month||0],league:['League points',u=>u.leaguePoints||0]};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let raceTimer=null,rewoundUsers=null,serverSnapshots=[],duels=[],quests=[],leagueRows=[],messages=[],playlist=[],reactions=[],hypeEvents=[],adminStatus={configured:false,authenticated:false},featureSettings={sound:false},focusTimer=null,focusRemaining=1500,raidGoal=Number(localStorage.getItem('stalk.raidGoal'))||30,lastRaidTotal=null,users=[],sort='total',topic='',query='',activityStatus='all',activityPlayer='',lastUpdated=0,hasLoaded=false,previousActivity=new Set(),snapshots=readStore('stalk.snapshots',[]),champions=readStore('stalk.champions',[]),daily=null,loadError='',lastSolved=0,chartInstances=[];
function readStore(k,fallback){try{return JSON.parse(localStorage.getItem(k))??fallback}catch{return fallback}}
