function nice(n){return Number(n||0).toLocaleString()}
function countUp(el,target){if(!el)return;target=Number(target)||0;const start=Number(el.dataset.value||0);el.dataset.value=String(target);if(start===target)return;if(matchMedia('(prefers-reduced-motion: reduce)').matches){el.textContent=nice(target);return}const t0=performance.now(),duration=620;const tick=now=>{const p=Math.min(1,(now-t0)/duration),ease=1-Math.pow(1-p,3);el.textContent=nice(Math.round(start+(target-start)*ease));if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}
function isoDay(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function getCalendar(u){try{return typeof u.calendar==='string'?JSON.parse(u.calendar||'{}'):(u.calendar||{})}catch{return {}}}
function activityDays(u){const cal=getCalendar(u);return Object.entries(cal).reduce((o,[t,n])=>{const d=isoDay(new Date(Number(t)*1000));o[d]=(o[d]||0)+Number(n||0);return o},{})}
function streakInfo(u){const days=activityDays(u),today=new Date();let cur=0,longest=0,run=0;const dates=Object.keys(days).sort();for(const d of dates){const date=new Date(d+'T12:00:00');if(!run||date- new Date((dates[dates.indexOf(d)-1]||d)+'T12:00:00')===86400000)run++;else run=1;longest=Math.max(longest,run)}const t=isoDay(today),y=isoDay(new Date(today-86400000));let cursor=days[t]?new Date(t+'T12:00:00'):days[y]?new Date(y+'T12:00:00'):null;while(cursor&&days[isoDay(cursor)]){cur++;cursor.setDate(cursor.getDate()-1)}return {current:cur,longest}}
function levelFor(u){const st=streakInfo(u),xp=(u.easy||0)*10+(u.medium||0)*25+(u.hard||0)*60+Math.min(st.current,30)*5;const levels=[['Rookie',0],['Grinder',500],['Hustler',1800],['Beast',5000],['Legend',12000]];let i=levels.findIndex((x,j)=>xp>=x[1]&&(j===levels.length-1||xp<levels[j+1][1]));i=Math.max(0,i);return {xp,name:levels[i][0],from:levels[i][1],to:levels[i+1]?.[1]||levels[i][1]+5000,progress:levels[i+1]?Math.min(100,(xp-levels[i][1])/(levels[i+1][1]-levels[i][1])*100):100}}
function badgesFor(u){const st=streakInfo(u),days=activityDays(u),recent30=Object.entries(days).filter(([d])=>(Date.now()-new Date(d+'T23:59:59').getTime())<30*864e5).reduce((n,[,c])=>n+c,0),hours=(u.recent||[]).filter(r=>new Date(Number(r.timestamp)*1000).getHours()>=0&&new Date(Number(r.timestamp)*1000).getHours()<5).length;const accepted=(u.recent||[]).filter(r=>r.statusDisplay==='Accepted');let comeback=false;for(let i=1;i<accepted.length;i++)if(Number(accepted[i-1].timestamp)-Number(accepted[i].timestamp)>=7*86400)comeback=true;return [['💀 Hard Slayer',(u.hard||0)>=10],['🔥 7-Day Streak',st.longest>=7],['⚡ 30-Day Streak',st.longest>=30],['🦉 Night Owl',hours>=3],['↩ Comeback Kid',comeback],['💯 Century',recent30>=100]].filter(x=>x[1]).map(x=>x[0])}
function currentSorted(){return [...(rewoundUsers||users)].filter(u=>`${u.name} ${u.username}`.toLowerCase().includes(query)).sort((a,b)=>metric(b)-metric(a)||(b.total||0)-(a.total||0))}
function toast(html,ms=3300){const el=document.createElement('div');el.className='toast';el.innerHTML=html;$('#toast-root').append(el);setTimeout(()=>el.remove(),ms)}
function pulseConfetti(){if(window.matchMedia('(prefers-reduced-motion: reduce)').matches||!window.confetti)return;window.confetti({particleCount:75,spread:65,origin:{y:.7},colors:['#C6F135','#FF5A36','#3D5AFE']})}
function playAdminSound(enabled){if(!enabled)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(660,ctx.currentTime);osc.frequency.exponentialRampToValueAtTime(990,ctx.currentTime+.12);gain.gain.setValueAtTime(.0001,ctx.currentTime);gain.gain.exponentialRampToValueAtTime(.08,ctx.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.22);osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+.23);osc.onended=()=>ctx.close()}catch{}}
function render(){const list=currentSorted();$('#rank-label').textContent=(topic||SORTS[sort][0]).toUpperCase();updateOverview();renderRaid();renderPodium(list);renderBoard(list);renderFeed();renderSelects();renderSquadHeatmaps();renderDaily();renderCompetitive();renderMessages();renderPlaylist();saveSnapshot()}
function updateOverview(){const view=rewoundUsers||users,sum=(key,arr=view)=>arr.reduce((n,u)=>n+(Number(u[key])||0),0),all=sum('total');countUp($('#hero-total'),all);countUp($('#stat-players'),view.length);countUp($('#stat-hard'),sum('hard'));countUp($('#stat-week'),sum('week'));const top=[...view].sort((a,b)=>(b.rating||0)-(a.rating||0))[0];if(top?.rating)countUp($('#stat-rating'),top.rating);else $('#stat-rating').textContent='—';$('#stat-rating-name').textContent=top?String(top.name||top.username).toUpperCase():'ARENA MVP';$('#weekly-total').textContent=`${nice(sum('week'))} THIS WEEK`;if(all>lastSolved&&lastSolved>0)pulseConfetti();lastSolved=all}
function renderRaid(){const total=users.reduce((n,u)=>n+(Number(u.today)||0),0),goal=raidGoal;$('#raid-done').textContent=nice(total);$('#raid-target').textContent=nice(goal);$('#raid-goal').value=String(goal);const pct=Math.min(100,Math.round(total/goal*100));$('#raid-fill').style.width=`${pct}%`;$('#raid-progress').setAttribute('aria-valuemax',goal);$('#raid-progress').setAttribute('aria-valuenow',Math.min(goal,total));$('#raid-message').textContent=total>=goal?'RAID CLEARED · Your squad showed up today.':`${nice(goal-total)} more submission${goal-total===1?'':'s'} to clear today’s raid.`;$('#raid-contributors').innerHTML=[...users].sort((a,b)=>(b.today||0)-(a.today||0)).filter(u=>u.today>0).slice(0,3).map((u,i)=>`<span class="raid-contributor"><b>#${i+1}</b> ${esc(u.name||u.username)} <small>${nice(u.today)} today</small></span>`).join('')||'<span class="raid-contributor muted">First submission takes the lead.</span>';if(lastRaidTotal!==null&&lastRaidTotal<goal&&total>=goal&&localStorage.getItem('stalk.raidCleared')!==isoDay()){playAdminSound(featureSettings.sound);localStorage.setItem('stalk.raidCleared',isoDay());pulseConfetti();toast('<b>Daily raid cleared!</b> The squad hit its submission goal.')}lastRaidTotal=total}
function renderPodium(list){$('#podium').innerHTML=list.slice(0,3).map((u,i)=>`<article class="podium-card glass ${i===0?'first':''}" data-profile="${esc(u.username)}" tabindex="0" role="button" aria-label="Open ${esc(u.name)} profile"><span class="podium-rank">0${i+1}</span><img class="avatar" src="${esc(u.avatar||'')}" alt="" onerror="this.style.visibility='hidden'"><div class="podium-info"><b>${esc(u.name||u.username)}</b><small>@${esc(u.username)} · ${nice(metric(u))} ${esc(lensLabel())}</small></div>${i===0?'<span class="crown" aria-label="Champion">♛</span>':''}</article>`).join('')||'<div class="empty">Add your crew to crown the first champion.</div>'}
function renderBoard(list){const board=$('#board');const before=new Map([...board.querySelectorAll('.row')].map(el=>[el.dataset.profile,el.getBoundingClientRect().top]));if(!list.length){board.innerHTML=loadError?`<div class="empty"><b>Couldn’t reach the arena</b>${esc(loadError)}<br><button class="btn small" onclick="load(true)">Try again</button></div>`:users.length?'<div class="empty"><b>No matching players</b>Try a different name.</div>':'<div class="empty"><b>Your arena is waiting</b>Add a LeetCode username to get started.</div>';return}board.innerHTML=list.map((u,i)=>{const id=u.username.toLowerCase(),history=snapshots.filter(s=>s.day!==isoDay()).at(-1),oldUsers=history?.users||[],key=topic?topic:sort,oldOrder=[...oldUsers].sort((a,b)=>(Number(b[key]??b.tags?.[key]??0)-Number(a[key]??a.tags?.[key]??0))||(b.total||0)-(a.total||0)),old=oldOrder.findIndex(x=>x.username.toLowerCase()===id),delta=old<0?'':old-i;const change=delta>0?`<small class="rank-change rank-up">↑${delta}</small>`:delta<0?`<small class="rank-change rank-down">↓${-delta}</small>`:'';const st=streakInfo(u),lv=levelFor(u),rival=i?list[i-1]:null,rivalCopy=rival?` · ${esc(rival.name||rival.username)} +${nice(Math.max(0,metric(rival)-metric(u)))} ahead`:' · you’re the target';return `<article class="row" style="animation-delay:${Math.min(i*35,350)}ms" data-profile="${esc(u.username)}"><div class="player-cell"><span class="rk rank-${i+1}">${String(i+1).padStart(2,'0')}${change}</span><img class="avatar" src="${esc(u.avatar||'')}" alt="" onerror="this.style.visibility='hidden'"><div class="player-meta"><a href="#/player/${encodeURIComponent(u.username)}"><b>${esc(u.name||u.username)} ${st.current?`<span class="streak">🔥${st.current}</span>`:''}</b></a><small>@${esc(u.username)}<span class="rival-copy">${rivalCopy}</span>${u.error?` · ${esc(u.error)}`:''}</small></div><button class="row-remove" data-remove="${esc(u.username)}" aria-label="Remove ${esc(u.username)}" title="Remove player">✕</button></div><div class="difficulty-chips"><span class="e">E ${nice(u.easy)}</span><span class="m">M ${nice(u.medium)}</span><span class="h">H ${nice(u.hard)}</span></div><div class="metric">${nice(metric(u))}<small class="metric-label">${esc(lensLabel())}</small></div><div class="level-cell"><span class="level-badge">${lv.name} · ${nice(lv.xp)} XP</span></div></article>`}).join('');const after=[...board.querySelectorAll('.row')];for(const el of after){const y=before.get(el.dataset.profile);if(y==null)continue;const delta=y-el.getBoundingClientRect().top;if(Math.abs(delta)<1)continue;el.style.transition='none';el.style.transform=`translateY(${delta}px)`;requestAnimationFrame(()=>{el.style.transition='';el.style.transform='';})}}
function renderFeed(){const all=users.flatMap(u=>(u.recent||[]).map(r=>({...r,username:u.username,who:u.name||u.username}))).sort((a,b)=>Number(b.timestamp)-Number(a.timestamp));const fresh=[];for(const r of all){const key=`${r.username}-${r.timestamp}-${r.titleSlug}`;if(!previousActivity.has(key)&&r.statusDisplay==='Accepted')fresh.push(r);previousActivity.add(key)}if(fresh.length&&hasLoaded){playAdminSound(featureSettings.sound);toast(`✨ <b>${esc(fresh[0].who)}</b> just cleared ${esc(fresh[0].title)}!`);if('Notification'in window&&Notification.permission==='granted')new Notification('New accepted submission',{body:`${fresh[0].who} cleared ${fresh[0].title}`})}const feed=all.filter(r=>(activityStatus==='all'||(activityStatus==='Accepted'?r.statusDisplay==='Accepted':r.statusDisplay!=='Accepted'))&&(!activityPlayer||r.username.toLowerCase()===activityPlayer)&&(!query||`${r.who} ${r.title}`.toLowerCase().includes(query)));$('#feed').innerHTML=[...feed.slice(0,30).map(r=>`<div class="activity-item"><span class="activity-status ${r.statusDisplay==='Accepted'?'':'bad'}">${r.statusDisplay==='Accepted'?'✓':'×'}</span><div class="activity-copy"><b>${esc(r.who)}</b> <span class="${r.statusDisplay==='Accepted'?'ok':'bad'}">${esc(r.statusDisplay)}</span><br><a href="https://leetcode.com/problems/${encodeURIComponent(r.titleSlug||'')}/" target="_blank" rel="noopener">${esc(r.title)}</a><small>${esc(r.lang)} · @${esc(r.username)}</small></div><time class="activity-time">${ago(r.timestamp)}</time><div class="reaction-row">${['🔥','👏','💀','😭'].map(em=>{const key=`${r.username}:${r.timestamp}:${r.titleSlug}`,count=reactions.filter(x=>x.activityKey===key&&x.emoji===em).length;return `<button data-react="${em}" data-key="${esc(key)}">${em} ${count||''}</button>`}).join('')}</div></div>`),...hypeEvents.filter(x=>['hardSolve','overtake','duelResult','questComplete'].includes(x.type)).slice(0,5).map(x=>`<div class="activity-item hype-item"><span class="activity-status">✦</span><div class="activity-copy"><b>ARENA HYPE</b><br>${esc(x.payload?.text||x.type)}<small>${ago(x.createdAt/1000)}</small></div></div>`)].join('')||'<div class="empty">No matching submissions yet.</div>'}
function renderSelects(){const sel=$('#topic'),tags=[...new Set(users.flatMap(u=>Object.keys(u.tags||{})))].sort(),old=topic;sel.innerHTML='<option value="">Topic lens…</option>'+tags.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');sel.value=tags.includes(old)?old:'';if(!tags.includes(old))topic='';const player=$('#activity-player'),prev=activityPlayer;player.innerHTML='<option value="">All players</option>'+users.map(u=>`<option value="${esc(u.username.toLowerCase())}">${esc(u.name||u.username)}</option>`).join('');player.value=users.some(u=>u.username.toLowerCase()===prev)?prev:'';activityPlayer=player.value}
function renderSquadHeatmaps(){const host=$('#squad-heatmaps');if(!users.length){host.innerHTML='<div class="empty">Add players to see the squad activity calendars.</div>';return}const today=new Date(),start=new Date(today);start.setDate(today.getDate()-today.getDay()-357);host.innerHTML=users.map(u=>{const days=activityDays(u),st=streakInfo(u),cutoff=new Date(today);cutoff.setDate(cutoff.getDate()-363);const count=Object.entries(days).filter(([d])=>new Date(d+'T23:59:59')>=cutoff).reduce((n,[,v])=>n+v,0),cells=[];for(let i=0;i<364;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=isoDay(d),v=days[key]||0,level=v===0?0:v<2?1:v<4?2:v<7?3:4;cells.push(`<i class="heat-cell" data-level="${level}" data-date="${key}" data-count="${v}" title="${key}: ${v} submissions"></i>`)}return `<article class="squad-person glass"><header class="squad-person-head"><img class="avatar" src="${esc(u.avatar||'')}" alt="" onerror="this.style.visibility='hidden'"><div class="squad-person-name"><button data-profile="${esc(u.username)}">${esc(u.name||u.username)}</button><small>@${esc(u.username)}</small></div><div class="squad-person-stats"><b>${count.toLocaleString()}</b><small>ACTIVITY · 12M</small>${st.current?`<span>🔥 ${st.current} day streak</span>`:'<span>Ready to start a streak</span>'}</div></header><div class="squad-calendar-scroll"><div class="squad-calendar">${cells.join('')}</div></div><div class="squad-day-detail" aria-live="polite">Hover or tap a day to see its submission count.</div></article>`}).join('')}
function showDayCount(cell){const card=cell.closest('.squad-person'),detail=card?.querySelector('.squad-day-detail');if(!detail)return;const date=new Date(cell.dataset.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'}),count=Number(cell.dataset.count)||0;detail.textContent=`${date} · ${count} submission${count===1?'':'s'}`}
function renderDaily(){const el=$('#daily-problem');if(!daily){el.innerHTML='<span class="muted">Daily challenge unavailable right now.</span>';return}const done=users.filter(u=>(u.recent||[]).some(r=>r.titleSlug===daily.question.titleSlug&&r.statusDisplay==='Accepted'));el.innerHTML=`<a href="https://leetcode.com/problems/${encodeURIComponent(daily.question.titleSlug)}/" target="_blank" rel="noopener">${esc(daily.question.title)}</a><div class="daily-tags"><span>${esc(daily.question.difficulty||'Daily')}</span>${(daily.question.topicTags||[]).slice(0,2).map(t=>`<span>${esc(t.name)}</span>`).join('')}</div><span class="daily-status">${done.length}/${users.length} PLAYERS CLEARED</span>`}
function renderCompetitive(){
 const activeDuels=duels.filter(d=>d.status==='active'),finishedDuels=duels.filter(d=>d.status==='finished').slice(0,3);$('#duel-list').innerHTML=activeDuels.map(d=>{const a=d.progress?.[d.challenger]||0,b=d.progress?.[d.opponent]||0,max=Math.max(1,a+b),remaining=Math.max(0,d.endAt-Date.now()),days=Math.floor(remaining/864e5),hours=Math.floor(remaining%864e5/36e5);return `<div class="duel-card"><div class="duel-top"><b>${esc(d.profiles?.[d.challenger]||d.challenger)} <span class="muted">vs</span> ${esc(d.profiles?.[d.opponent]||d.opponent)}</b><span class="duel-time">${days?days+'d ':''}${hours}h left</span></div><div class="duel-bar"><i style="width:${a/max*100}%"></i><i style="width:${b/max*100}%"></i></div><div class="duel-scores"><span>${a} ${esc(d.rule)}</span><span>target ${nice(d.target)}</span><span>${b} ${esc(d.rule)}</span></div></div>`}).join('')+finishedDuels.map(d=>`<div class="duel-card duel-winner">🏆 ${d.winner?`<b>${esc(d.profiles?.[d.winner]||d.winner)}</b> won the duel`:'Duel tied'} · ${esc(d.challenger)} vs ${esc(d.opponent)}</div>`).join('')||'<div class="feature-empty">No active duels. Challenge a friend and settle it in code.</div>';
 $('#quest-list').innerHTML=quests.filter(q=>q.status==='active').map(q=>`<div class="quest-card"><div class="quest-top"><b>${esc(q.title)}</b><span>${nice(q.progress)}/${nice(q.target)}</span></div><div class="quest-bar"><i style="width:${Math.min(100,q.progress/q.target*100)}%"></i></div><div class="quest-meta"><span>${esc(q.metric)} · ${(q.contributors||[]).length} contributors</span><b>${Math.min(100,Math.round(q.progress/q.target*100))}%</b></div></div>`).join('')||'<div class="feature-empty">No active quest. Ask an admin to launch one.</div>';
 $('#league-list').innerHTML=leagueRows.slice(0,8).map((u,i)=>`<div class="league-row"><span>${String(i+1).padStart(2,'0')}</span><span>${esc(u.name||u.username)}</span><b>${nice(u.points)} pts</b></div>`).join('')||'<div class="feature-empty">Points appear as the squad completes quests and duels.</div>';
}
function renderMessages(){const el=$('#message-list');if(!el)return;el.innerHTML=messages.slice(0,30).filter(m=>!m.deletedAt).map(m=>`<div class="message-item"><b>${esc(m.name)}</b> ${esc(m.text)}<small>${ago(m.createdAt/1000)}</small>${adminStatus.authenticated?`<button class="message-delete" data-message-delete="${esc(m._id)}" aria-label="Delete message">×</button>`:''}</div>`).join('')||'<div class="feature-empty">The wall is quiet. Drop the first hype line.</div>'}
function renderPlaylist(){const el=$('#playlist-list');if(!el)return;el.innerHTML=playlist.map(p=>`<div class="playlist-row"><a href="https://leetcode.com/problems/${encodeURIComponent(p.titleSlug)}/" target="_blank" rel="noopener">${esc(p.title)}</a><small>${(p.solvers||[]).length}/${users.length} solved${p.solverDetails?.length?` · ${p.solverDetails.map(x=>esc(x.name)).join(' → ')}`:''}</small>${adminStatus.authenticated?`<button data-playlist-remove="${esc(p.id)}" aria-label="Remove problem">×</button>`:''}</div>`).join('')||'<div class="feature-empty">Add a problem to start a club playlist.</div>'}
async function refreshFeatureData(){const oldFinished=new Set(duels.filter(d=>d.status==='finished').map(d=>d.id));const results=await Promise.allSettled([api('/api/duels'),api('/api/quests'),api('/api/league'),api('/api/messages'),api('/api/playlist'),api('/api/reactions?keys='+encodeURIComponent(users.flatMap(u=>(u.recent||[]).map(r=>`${u.username}:${r.timestamp}:${r.titleSlug}`)).slice(0,50).join(','))),api('/api/snapshots'),api('/api/events')]);if(results[0].status==='fulfilled'){duels=results[0].value;if(oldFinished.size&&duels.some(d=>d.status==='finished'&&!oldFinished.has(d.id))){pulseConfetti();toast('<b>Duel complete!</b> Check the winner banner.')}}if(results[1].status==='fulfilled')quests=results[1].value;if(results[2].status==='fulfilled')leagueRows=results[2].value;if(results[3].status==='fulfilled')messages=results[3].value;if(results[4].status==='fulfilled')playlist=results[4].value;if(results[5].status==='fulfilled')reactions=results[5].value;if(results[6].status==='fulfilled'){serverSnapshots=results[6].value;setupTimeMachine()}if(results[7].status==='fulfilled')hypeEvents=results[7].value;renderCompetitive();renderMessages();renderPlaylist()}
function setupTimeMachine(){const slider=$('#history-slider');if(!slider)return;slider.max=Math.max(0,serverSnapshots.length-1);slider.value=slider.max;slider.disabled=!serverSnapshots.length;$('#history-label').textContent=serverSnapshots.length?`Live · ${serverSnapshots.length} daily snapshots available`:'No saved snapshots yet. Configure MongoDB and sync to build history.'}
async function selectHistory(index){if(!serverSnapshots.length)return;const snap=serverSnapshots[Math.max(0,Math.min(serverSnapshots.length-1,index))];rewoundUsers=await api('/api/timemachine?day='+encodeURIComponent(snap.day));$('#history-label').textContent=`Viewing ${snap.day} · ${rewoundUsers.length} players in the snapshot`;$('.time-machine').classList.add('rewound');render()}
function showDuelForm(){openModal(`<div class="modal-header"><div><span class="eyebrow">SETTLE IT</span><h2>Challenge a friend</h2></div><button class="modal-close" aria-label="Close">×</button></div><form id="duel-form"><label class="admin-toggle">You<select id="duel-a">${users.map(u=>`<option value="${esc(u.username)}">${esc(u.name||u.username)}</option>`).join('')}</select></label><label class="admin-toggle">Rival<select id="duel-b">${users.map(u=>`<option value="${esc(u.username)}">${esc(u.name||u.username)}</option>`).join('')}</select></label><label class="admin-toggle">Rule<select id="duel-rule"><option value="mediums">Most Mediums</option><option value="hards">Most Hards</option><option value="solved">Most solved</option><option value="firstTo">First to target Hards</option></select></label><label class="admin-toggle">Target <input id="duel-target" type="number" min="1" max="100" value="5"></label><label class="admin-toggle">Duration <select id="duel-days"><option value="7">7 days</option><option value="3">3 days</option><option value="14">14 days</option></select></label><button class="btn primary" style="width:100%;margin-top:12px">Start duel ⚔</button></form>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#duel-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/duels',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenger:$('#duel-a').value,opponent:$('#duel-b').value,rule:$('#duel-rule').value,target:$('#duel-target').value,days:$('#duel-days').value})});closeModal();await refreshFeatureData();toast('<b>Duel started.</b> May the best coder win.')}catch(err){toast(esc(err.message))}};if(users[1])$('#duel-b').value=users[1].username}
function createQuest(){if(!adminStatus.authenticated){openAdmin();return}openModal(`<div class="modal-header"><div><span class="eyebrow">CREW MISSION</span><h2>Set a shared quest</h2></div><button class="modal-close" aria-label="Close">×</button></div><form id="quest-form"><input class="search" id="quest-title" style="width:100%" maxlength="80" placeholder="Quest name" required><label class="admin-toggle">Track<select id="quest-metric"><option value="weekly">Submissions this week</option><option value="today">Submissions today</option><option value="solved">Problems solved</option><option value="hards">Hards solved</option></select></label><label class="admin-toggle">Goal<input id="quest-target" type="number" min="1" max="10000" value="100"></label><label class="admin-toggle">Duration<select id="quest-days"><option value="7">7 days</option><option value="14">14 days</option><option value="30">30 days</option></select></label><button class="btn primary" style="width:100%;margin-top:12px">Launch quest</button></form>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#quest-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/quests',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:$('#quest-title').value,metric:$('#quest-metric').value,target:$('#quest-target').value,days:$('#quest-days').value})});closeModal();await refreshFeatureData()}catch(err){if(err.status===401)openAdmin();else toast(esc(err.message))}}}
async function openAdmin(){try{adminStatus=await api('/api/admin/status')}catch(err){toast(esc(err.message));return}if(!adminStatus.configured){openModal(`<div class="modal-header"><div><span class="eyebrow">ADMIN ACCESS</span><h2>Set your admin password</h2></div><button class="modal-close" aria-label="Close">×</button></div><p class="muted">Set ADMIN_PASSWORD in your local environment or Vercel project settings. Admin writes stay locked until configured.</p>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;return}if(!adminStatus.authenticated){openModal(`<div class="modal-header"><div><span class="eyebrow">ADMIN ACCESS</span><h2>Unlock club controls</h2></div><button class="modal-close" aria-label="Close">×</button></div><form id="admin-login-form"><input id="admin-password" type="password" class="search" style="width:100%;height:44px" autocomplete="current-password" placeholder="Admin password" required><p id="admin-error" class="muted">Player management, quests, and integrations are admin-only.</p><button class="btn primary" style="width:100%">Sign in</button></form>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#admin-login-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password:$('#admin-password').value})});adminStatus.authenticated=true;openAdmin()}catch(err){$('#admin-error').textContent=err.message}};return}const settings=await api('/api/admin/settings'),logs=await api('/api/admin/logs');featureSettings.sound=Boolean(settings.sound);const toggles=Object.entries(settings.notifications||{});openModal(`<div class="modal-header"><div><span class="eyebrow">CONTROL ROOM</span><h2>Admin settings</h2></div><button class="modal-close" aria-label="Close">×</button></div><div class="admin-actions"><button class="btn small" id="admin-logout">Sign out</button><button class="btn small" id="notification-enable">Enable browser alerts</button><a class="btn small" href="/api/export?format=csv">Export CSV</a><a class="btn small" href="/api/export?format=json">Export JSON</a></div><div id="admin-settings">${toggles.map(([k,v])=>`<label class="admin-toggle"><span>${esc(k.replace(/[A-Z]/g,' $&').replace(/^./,x=>x.toUpperCase()))}<small>Discord / Telegram event</small></span><input type="checkbox" data-setting="${esc(k)}" ${v?'checked':''}></label>`).join('')}<label class="admin-toggle">Reminder timezone<input id="setting-zone" value="${esc(settings.timezone)}"></label><label class="admin-toggle">Streak alert hour<input id="setting-hour" type="number" min="0" max="23" value="${settings.streakDangerHour}"></label><label class="admin-toggle"><span>Sound effects<small>Play a short chime for arena events</small></span><input id="setting-sound" type="checkbox" ${settings.sound?'checked':''}></label></div><button class="btn primary" id="settings-save" style="margin-top:12px">Save settings</button><div class="eyebrow" style="margin-top:18px">RECENT SYNC FAILURES</div><div class="admin-log">${logs.map(x=>`${esc(new Date(x.createdAt).toLocaleString())} · ${esc(x.username)} · ${esc(x.message)}`).join('<br>')||'No failed syncs logged.'}</div>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#admin-logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'});adminStatus.authenticated=false;openAdmin()};$('#notification-enable').onclick=async()=>{if('Notification'in window){await enablePush()}else toast('Browser notifications are unavailable.')};$('#settings-save').onclick=async()=>{const notifications={};$$('[data-setting]').forEach(x=>notifications[x.dataset.setting]=x.checked);try{await api('/api/admin/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({notifications,timezone:$('#setting-zone').value,streakDangerHour:$('#setting-hour').value,sound:$('#setting-sound').checked})});settings.sound=$('#setting-sound').checked;featureSettings.sound=settings.sound;toast('<b>Settings saved</b>')}catch(err){toast(esc(err.message))}}}
async function refreshHistory(){try{serverSnapshots=await api('/api/snapshots');setupTimeMachine()}catch{}}
function base64ToBytes(value){const pad='='.repeat((4-value.length%4)%4),raw=atob((value+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window)){toast('Push notifications are not supported here.');return}const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Notification permission was not granted.');return}try{const {publicKey}=await api('/api/push/key'),registration=await navigator.serviceWorker.ready,subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64ToBytes(publicKey)});await api('/api/push/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({subscription:subscription.toJSON()})});toast('<b>Push alerts enabled</b> You’ll hear about new clears and overtakes.')}catch(e){toast(esc(e.message))}}
function randomReactor(){let id=localStorage.getItem('stalk.reactor');if(!id){id=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;localStorage.setItem('stalk.reactor',id)}return id}
function ago(t){const s=Math.max(0,Date.now()/1000-Number(t));return s<60?'now':s<3600?`${Math.floor(s/60)}m`:s<86400?`${Math.floor(s/3600)}h`:`${Math.floor(s/86400)}d`}
function saveSnapshot(){if(!users.length)return;const snap={day:isoDay(),users:users.map(u=>({username:u.username,total:u.total,easy:u.easy,medium:u.medium,hard:u.hard,rating:u.rating,today:u.today,week:u.week,month:u.month,leaguePoints:u.leaguePoints||0,tags:u.tags||{}}))};if(snapshots.at(-1)?.day!==snap.day)snapshots.push(snap);else snapshots[snapshots.length-1]=snap;snapshots=snapshots.slice(-400);writeStore('stalk.snapshots',snapshots);const monday=new Date();monday.setHours(0,0,0,0);monday.setDate(monday.getDate()-((monday.getDay()+6)%7));const weekKey=isoDay(monday);if(!champions.some(c=>c.week===weekKey)){const winner=[...users].sort((a,b)=>(b.week||0)-(a.week||0))[0];if(winner){champions.unshift({week:weekKey,username:winner.username,name:winner.name,score:winner.week||0});champions=champions.slice(0,40);writeStore('stalk.champions',champions)}}}
function calcContest(){const now=new Date();const monday=new Date(now);monday.setHours(0,0,0,0);monday.setDate(monday.getDate()+((8-monday.getDay())%7||7));const seasonMs=monday-now;$('#season-countdown').textContent=`SEASON RESET · ${Math.floor(seasonMs/864e5)}D ${Math.floor(seasonMs%864e5/36e5)}H`;const candidates=[],dayMs=864e5,anchor=Date.UTC(2019,5,1,14,30);for(let i=0;i<16;i++){const d=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+i));if(d.getUTCDay()===0){const t=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),2,30);if(t>now.getTime())candidates.push({name:'Weekly Contest',date:new Date(t)})}if(d.getUTCDay()===6){const t=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),14,30);if(t>now.getTime()&&(t-anchor)%(14*dayMs)===0)candidates.push({name:'Biweekly Contest',date:new Date(t)})}}const next=candidates.sort((a,b)=>a.date-b.date)[0],el=$('#contest-countdown');if(!next){el.textContent='Contest schedule unavailable';return}const ms=next.date-Date.now(),days=Math.floor(ms/864e5),hours=Math.floor(ms%864e5/36e5),mins=Math.floor(ms%36e5/6e4);el.textContent=`NEXT ${next.name.toUpperCase()} · ${days?days+'D ':''}${hours}H ${mins}M`}
async function api(url,options){const r=await fetch(url,options);let j;try{j=await r.json()}catch{j={}}if(!r.ok){const e=Error(j.error||`Request failed (${r.status})`);e.status=r.status;throw e}return j}
async function load(force=false){const b=$('#sync');if(force){b.disabled=true;b.classList.add('spinning');$('#updated-label').textContent='Syncing…'}try{const [data,extra]=await Promise.all([api(force?'/api/data?refresh=1':'/api/data'),api('/api/extras').catch(()=>({daily:null}))]);users=data;daily=extra.daily||null;loadError='';lastUpdated=Date.now();render();hasLoaded=true;await refreshFeatureData();adminStatus=await api('/api/admin/status').catch(()=>adminStatus);renderPlaylist();if(!localStorage.getItem('stalk.whatsNew.v3'))openWhatsNew();$('#updated-label').textContent='Live · just updated'}catch(e){loadError=e.message;renderBoard(currentSorted());$('#updated-label').textContent='Offline · tap sync'}finally{if(force){b.disabled=false;b.classList.remove('spinning')}}}
function applySort(k){sort=k;topic='';$('#topic').value='';$$('#sorts .chip').forEach(x=>x.classList.toggle('on',x.dataset.k===k));render()}
function openModal(html,wide=false){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-backdrop><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</section></div>`;$('#modal-root').querySelector('[data-backdrop]').onclick=e=>{if(e.target.dataset.backdrop!==undefined)closeModal()};const title=$('#modal-root').querySelector('.modal-header h2');if(title){title.id='dialog-title';$('#modal-root').querySelector('.modal').setAttribute('aria-labelledby','dialog-title')}$('#modal-root').querySelector('.modal-close')?.focus()}
