function openProfile(username){const u=users.find(x=>x.username.toLowerCase()===username.toLowerCase());if(!u)return;location.hash=`/player/${encodeURIComponent(u.username)}`;const st=streakInfo(u),lv=levelFor(u),badges=badgesFor(u);const days=activityDays(u),start=new Date();start.setDate(start.getDate()-363);const cells=[];for(let i=0;i<364;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=isoDay(d),v=days[key]||0;cells.push(`<i class="heat-cell" title="${key}: ${v} submissions" data-level="${v===0?0:v<2?1:v<4?2:v<7?3:4}"></i>`)}const recent=(u.recent||[]).slice().sort((a,b)=>b.timestamp-a.timestamp);openModal(`<div class="modal-header"><div><span class="eyebrow">PLAYER DOSSIER</span><h2>${esc(u.name||u.username)}</h2></div><button class="modal-close" aria-label="Close">×</button></div><div class="profile-top"><img class="avatar" src="${esc(u.avatar||'')}" alt="" onerror="this.style.visibility='hidden'"><div style="flex:1"><h3>@${esc(u.username)} · ${lv.name}</h3><small class="muted">${nice(lv.xp)} XP · ${st.current} day streak · longest ${st.longest} days</small><div class="xp-track"><i style="width:${lv.progress}%"></i></div></div></div><div class="profile-stats">${[['SOLVED',u.total],['EASY',u.easy],['MEDIUM',u.medium],['HARD',u.hard],['RATING',u.rating],['7D',u.week],['30D',u.month],['CONTESTS',u.contests]].map(([k,v])=>`<div class="profile-stat"><b>${nice(v)}</b><small>${k}</small></div>`).join('')}</div><div class="eyebrow">UNLOCKED BADGES</div><div class="badge-list">${badges.map(x=>`<span class="badge">${esc(x)}</span>`).join('')||'<span class="muted">Your next badge is waiting.</span>'}</div><div class="eyebrow">LAST 12 MONTHS · SUBMISSION HEATMAP</div><div class="heat-wrap"><div class="heatmap">${cells.join('')}</div></div><div id="profile-insights" class="profile-insights"><span class="muted">Loading player insights…</span></div><div class="chart-grid"><div class="chart-box"><h3>TOPIC MASTERY</h3><canvas id="topic-chart"></canvas></div><div class="chart-box"><h3>RATING HISTORY · LOCAL SNAPSHOTS</h3><canvas id="rating-chart"></canvas></div></div><div class="focus-clock"><div><span class="eyebrow">FOCUS SPRINT</span><strong id="focus-display">25:00</strong><small id="focus-total" class="muted"></small></div><button class="btn small" id="focus-toggle">Start 25 min</button></div><div class="eyebrow">PROFILE BADGE · EMBED IN README</div><textarea id="badge-code" class="badge-embed" readonly></textarea><button class="btn small" id="badge-copy">Copy badge code</button><div id="duel-history" class="feature-list"></div><div class="eyebrow" style="margin-top:17px">RECENT SUBMISSIONS</div><div class="feed">${recent.slice(0,8).map(r=>`<div class="activity-item"><span class="activity-status ${r.statusDisplay==='Accepted'?'':'bad'}">${r.statusDisplay==='Accepted'?'✓':'×'}</span><div class="activity-copy"><a href="https://leetcode.com/problems/${encodeURIComponent(r.titleSlug)}/" target="_blank" rel="noopener">${esc(r.title)}</a><small>${esc(r.statusDisplay)} · ${esc(r.lang)}</small></div><time class="activity-time">${ago(r.timestamp)}</time></div>`).join('')||'<span class="muted">No recent submissions.</span>'}</div><div style="display:flex;gap:8px;margin-top:14px"><button class="btn small" data-compare-one="${esc(u.username)}">⚔ Compare</button><button class="btn small" data-download-profile="${esc(u.username)}">▧ Download share card</button></div>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#modal-root').querySelector('[data-compare-one]').onclick=()=>openCompare(u.username);$('#modal-root').querySelector('[data-download-profile]').onclick=()=>downloadCard(u);drawCharts(u);loadProfileExtras(u);}
function chartDefaults(){return {responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{r:{grid:{color:'rgba(140,150,170,.15)'},angleLines:{color:'rgba(140,150,170,.15)'},pointLabels:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted'),font:{size:9}},ticks:{display:false}}}}}
function drawCharts(u){if(!window.Chart)return;const tags=Object.entries(u.tags||{}).sort((a,b)=>b[1]-a[1]).slice(0,7);const a=$('#topic-chart'),b=$('#rating-chart');if(a){chartInstances.push(new Chart(a,{type:'radar',data:{labels:tags.map(x=>x[0]),datasets:[{data:tags.map(x=>x[1]),backgroundColor:'#c6f1352b',borderColor:'#C6F135',pointBackgroundColor:'#C6F135',borderWidth:2}]},options:chartDefaults()}))}if(b){const history=snapshots.filter(s=>s.users.some(x=>x.username.toLowerCase()===u.username.toLowerCase())).slice(-14);const values=history.map(s=>s.users.find(x=>x.username.toLowerCase()===u.username.toLowerCase()));chartInstances.push(new Chart(b,{type:'line',data:{labels:history.map(s=>s.day.slice(5)),datasets:[{data:values.map(x=>x.rating||0),borderColor:'#3D5AFE',backgroundColor:'#3D5AFE22',fill:true,tension:.3,pointRadius:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:8}},grid:{display:false}},y:{ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:8}},grid:{color:'rgba(140,150,170,.12)'}}}}}))}}
function openCompare(initial=''){location.hash='#/compare';const options=users.map(u=>`<option value="${esc(u.username)}">${esc(u.name||u.username)}</option>`).join('');openModal(`<div class="modal-header"><div><span class="eyebrow">HEAD TO HEAD</span><h2>Pick your opponents</h2></div><button class="modal-close" aria-label="Close">×</button></div><div class="compare-selects"><select id="compare-a" aria-label="First player">${options}</select><select id="compare-b" aria-label="Second player">${options}</select></div><div id="compare-result"></div>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#compare-a').value=initial||users[0]?.username||'';$('#compare-b').value=users.find(u=>u.username!==$('#compare-a').value)?.username||users[0]?.username||'';$('#compare-a').onchange=$('#compare-b').onchange=renderCompare;renderCompare()}
function renderCompare(){chartInstances.forEach(c=>c.destroy());chartInstances=[];const a=users.find(u=>u.username===$('#compare-a')?.value),b=users.find(u=>u.username===$('#compare-b')?.value);if(!a||!b)return;const pairs=[['Solved',a.total,b.total],['Easy',a.easy,b.easy],['Medium',a.medium,b.medium],['Hard',a.hard,b.hard],['Rating',a.rating,b.rating],['This week',a.week,b.week]];const winner=(a.total||0)===(b.total||0)?'It’s a dead heat. Time to settle it in the arena.':(a.total||0)>(b.total||0)?`${a.name||a.username} leads by ${(a.total||0)-(b.total||0)} solved problems.`:`${b.name||b.username} leads by ${(b.total||0)-(a.total||0)} solved problems.`;$('#compare-result').innerHTML=`<div class="compare-bars">${pairs.map(([n,x,y])=>{const max=Math.max(1,x||0,y||0);return `<div class="compare-line"><span>${n}</span><div class="bar-pair"><i style="width:${(x||0)/max*50}%"></i><i style="width:${(y||0)/max*50}%"></i></div><span>${nice(x)} · ${nice(y)}</span></div>`}).join('')}</div><div class="verdict">${esc(winner)}</div><div class="chart-box" style="margin-top:12px"><canvas id="compare-chart"></canvas></div>`;if(window.Chart){const ctx=$('#compare-chart');chartInstances.push(new Chart(ctx,{type:'radar',data:{labels:['Solved','Easy','Medium','Hard','Rating','Week'],datasets:[{label:a.name,data:[a.total,a.easy,a.medium,a.hard,a.rating,a.week],borderColor:'#C6F135',backgroundColor:'#C6F13522'},{label:b.name,data:[b.total,b.easy,b.medium,b.hard,b.rating,b.week],borderColor:'#3D5AFE',backgroundColor:'#3D5AFE22'}]},options:{...chartDefaults(),plugins:{legend:{display:true,labels:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:9}}}}}}))}}
function showChampions(){location.hash='#/champions';const palette=['#C6F135','#3D5AFE','#FF5A36','#B49AFF','#22C55E','#F5A524'];openModal(`<div class="modal-header"><div><span class="eyebrow">SEASON ARCHIVE</span><h2>Hall of champions</h2></div><button class="modal-close" aria-label="Close">×</button></div>${champions.length?champions.map((c,i)=>`<div class="activity-item"><span class="podium-rank">${i===0?'♛':String(i+1).padStart(2,'0')}</span><div class="activity-copy"><b>${esc(c.name||c.username)}</b><small>Week of ${esc(c.week)} · ${nice(c.score)} submissions</small></div></div>`).join(''):'<div class="empty">Champions are saved in this browser each Monday. The first trophy is up for grabs.</div>'}<div class="chart-box" style="margin-top:14px"><h3>THE RACE · LOCAL DAILY SNAPSHOTS</h3><canvas id="race-chart"></canvas></div><button class="btn small" id="race-play" style="margin-top:10px">▶ Play race</button>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;drawRace(palette)}
function drawRace(palette){const canvas=$('#race-chart');if(!window.Chart||!canvas||!snapshots.length)return;const series=users.map((u,i)=>({u,color:palette[i%palette.length],values:snapshots.map(s=>s.users.find(x=>x.username.toLowerCase()===u.username.toLowerCase())?.total??null)})).filter(x=>x.values.some(v=>v!=null));const frameData=series.map(s=>s.values.map(()=>null));const chart=new Chart(canvas,{type:'line',data:{labels:snapshots.map(s=>s.day.slice(5)),datasets:series.map((s,i)=>({label:s.u.name||s.u.username,data:frameData[i],borderColor:s.color,backgroundColor:s.color+'22',tension:.28,pointRadius:2}))},options:{responsive:true,maintainAspectRatio:false,animation:{duration:180},plugins:{legend:{display:true,labels:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:9}}}},scales:{x:{ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:8}},grid:{display:false}},y:{ticks:{color:getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),font:{size:8}},grid:{color:'rgba(140,150,170,.12)'}}}}});chartInstances.push(chart);let frame=0;const btn=$('#race-play');btn.onclick=()=>{if(raceTimer){clearInterval(raceTimer);raceTimer=null;btn.textContent='▶ Play race';return}if(frame>=snapshots.length){frame=0;chart.data.datasets.forEach(ds=>ds.data.fill(null))}btn.textContent='Ⅱ Pause race';raceTimer=setInterval(()=>{for(let i=0;i<series.length;i++)chart.data.datasets[i].data[frame]=series[i].values[frame];chart.update();frame++;if(frame>=snapshots.length){clearInterval(raceTimer);raceTimer=null;btn.textContent='↻ Replay race'}},260)}}
function shareText(){return `stalkmyleetcode · The Coding Club Ledger\n${lensLabel()}\n${currentSorted().slice(0,10).map((u,i)=>`${i+1}. ${u.name||u.username} — ${metric(u)} ${lensLabel()}`).join('\n')}\n${location.origin}${location.pathname}`}
async function shareBoard(){openModal(`<div class="modal-header"><div><span class="eyebrow">PASS THE HYPE</span><h2>Share your arena</h2></div><button class="modal-close" aria-label="Close">×</button></div><p class="muted">Copy the current standings or download a ready-to-post share card.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="copy-share">↗ Copy board + link</button><button class="btn" id="download-share">▧ Download PNG</button><button class="btn" id="native-share">Share…</button></div><div class="chart-box" style="height:320px;margin-top:14px;background:#0B0D12"><canvas id="share-preview"></canvas></div>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;const draw=async()=>{const blob=await createShareCard();if(!blob)return;const img=new Image();img.onload=()=>{const c=$('#share-preview'),ctx=c.getContext('2d');c.width=img.width;c.height=img.height;ctx.drawImage(img,0,0)};img.src=URL.createObjectURL(blob)};draw();$('#copy-share').onclick=async()=>{try{await navigator.clipboard.writeText(`${shareText()}\n${location.href.split('#')[0]}`);toast('<b>Board + link copied</b> Ready to share.')}catch{toast('Clipboard unavailable in this browser.')}};$('#download-share').onclick=()=>downloadCard();$('#native-share').onclick=async()=>{if(!navigator.share){toast('Web Share is not available here.');return}try{const blob=await createShareCard(),file=new File([blob],'stalkmyleetcode-board.png',{type:'image/png'});await navigator.share({title:'stalkmyleetcode leaderboard',text:shareText(),files:[file]})}catch(e){if(e.name!=='AbortError')toast('Could not open the share sheet.')}}}
function createShareCard(user=null){return new Promise(resolve=>{const w=1100,h=user?650:740,c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#0B0D12';x.fillRect(0,0,w,h);x.fillStyle='#171c27';x.fillRect(40,40,w-80,h-80);x.fillStyle='#C6F135';x.font='700 22px Space Grotesk, sans-serif';x.fillText('⌕  stalkmyleetcode',80,104);x.fillStyle='#8A93A6';x.font='14px Space Grotesk, sans-serif';x.fillText('THE CODING CLUB LEDGER  /  LIVE ARENA',80,135);x.fillStyle='#E8ECF4';x.font='700 54px Space Grotesk, sans-serif';x.fillText(user?(user.name||user.username):'Leaderboard',80,215);x.fillStyle='#C6F135';x.font='700 20px JetBrains Mono, monospace';x.fillText(user?`${nice(user.total)} solved · ${levelFor(user).name}`:lensLabel(),80,257);x.strokeStyle='#ffffff20';x.beginPath();x.moveTo(80,285);x.lineTo(w-80,285);x.stroke();const rows=user?[user]:currentSorted().slice(0,8);rows.forEach((u,i)=>{const y=330+i*44;x.fillStyle='#8A93A6';x.font='600 16px JetBrains Mono, monospace';x.fillText(String(i+1).padStart(2,'0'),85,y);x.fillStyle='#E8ECF4';x.font='600 18px Space Grotesk, sans-serif';x.fillText((u.name||u.username).slice(0,30),145,y);x.fillStyle='#C6F135';x.font='700 17px JetBrains Mono, monospace';x.textAlign='right';x.fillText(`${nice(user?u.total:metric(u))} ${user?'solved':lensLabel()}`,w-90,y);x.textAlign='left'});x.fillStyle='#8A93A6';x.font='12px Space Grotesk, sans-serif';x.fillText(new Date().toLocaleDateString(),80,h-65);c.toBlob(resolve,'image/png')} )}
async function downloadCard(user=null){const blob=await createShareCard(user);if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`stalkmyleetcode-${user?.username||'leaderboard'}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function openAdd(){openModal(`<div class="modal-header"><div><span class="eyebrow">SQUAD UP</span><h2>Add a player</h2></div><button class="modal-close" aria-label="Close">×</button></div><form id="add-form"><input id="new-username" class="search" style="width:100%;height:44px" maxlength="40" pattern="[A-Za-z0-9_-]{1,40}" placeholder="LeetCode username" aria-label="LeetCode username" required><p id="add-error" class="muted">We’ll check that the account exists before adding it.</p><button class="btn primary" style="width:100%">Add to arena →</button></form>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#add-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Checking…';try{await api('/api/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#new-username').value.trim()})});closeModal();toast('<b>Player added</b> Welcome to the arena.');await load()}catch(err){if(err.status===401){closeModal();openAdmin();return}$('#add-error').textContent=err.message;b.disabled=false;b.textContent='Add to arena →'}};$('#new-username').focus()}
function openPalette(){const actions=Object.entries(SORTS).map(([k,v])=>({name:`Switch lens · ${v[0]}`,run:()=>applySort(k)}));actions.push({name:'Sync now',run:()=>load(true)},{name:'Toggle light / dark theme',run:toggleTheme},{name:'Compare players',run:()=>openCompare()},{name:'Open champions hall',run:showChampions},{name:'Weekly wrapped',run:openWrapped},{name:'Challenge a friend',run:showDuelForm},{name:'Create crew quest',run:createQuest},{name:'Admin settings',run:openAdmin},{name:'Export CSV',run:()=>location.href='/api/export?format=csv'},{name:'Share leaderboard',run:shareBoard},{name:'Add a player',run:openAdd},...users.map(u=>({name:`Open player · ${u.name||u.username}`,run:()=>openProfile(u.username)})));$('#palette-root').innerHTML=`<div class="palette-backdrop" id="palette-backdrop"><div class="palette"><input id="palette-search" placeholder="Jump to anything…" aria-label="Search commands"><div class="palette-list" id="palette-list"></div></div></div>`;const draw=()=>{const q=$('#palette-search').value.toLowerCase();$('#palette-list').innerHTML=actions.filter(a=>a.name.toLowerCase().includes(q)).map((a,i)=>`<div class="palette-item" data-i="${i}">${esc(a.name)}<small>↵</small></div>`).join('');$$('.palette-item').forEach(el=>el.onclick=()=>{const a=actions.filter(x=>x.name.toLowerCase().includes(q))[Number(el.dataset.i)];$('#palette-root').innerHTML='';a?.run()})};$('#palette-search').oninput=draw;$('#palette-backdrop').onclick=e=>{if(e.target.id==='palette-backdrop')$('#palette-root').innerHTML=''};$('#palette-search').onkeydown=e=>{if(e.key==='Escape')$('#palette-root').innerHTML='';if(e.key==='Enter')$('#palette-list .palette-item')?.click()};draw();$('#palette-search').focus()}
function applyTheme(theme,persist=true){const next=theme==='light'?'light':'dark';document.documentElement.dataset.theme=next;const button=$('#theme-toggle');button.textContent=next==='dark'?'☼':'☾';button.setAttribute('aria-label',`Switch to ${next==='dark'?'light':'dark'} theme`);button.title=`Switch to ${next==='dark'?'light':'dark'} theme`;document.querySelector('meta[name=theme-color]').content=next==='dark'?'#0B0D12':'#f1f2f6';if(persist)localStorage.setItem('stalk.theme',next);if(window.Chart){const muted=getComputedStyle(document.documentElement).getPropertyValue('--muted').trim(),grid=next==='dark'?'rgba(140,150,170,.15)':'rgba(50,60,80,.14)';Chart.defaults.color=muted;chartInstances.forEach(c=>{for(const scale of Object.values(c.options.scales||{})){if(scale.ticks)scale.ticks.color=muted;if(scale.pointLabels)scale.pointLabels.color=muted;if(scale.grid)scale.grid.color=grid;if(scale.angleLines)scale.angleLines.color=grid}if(c.options.plugins?.legend?.labels)c.options.plugins.legend.labels.color=muted;c.update()})}}
function toggleTheme(){applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
async function loadProfileExtras(u){const box=$('#profile-insights');try{const [ins,recs,history]=await Promise.all([api(`/api/users/${encodeURIComponent(u.username)}/insights`),api(`/api/recommendations/${encodeURIComponent(u.username)}`),api(`/api/duels/history/${encodeURIComponent(u.username)}`)]);box.innerHTML=`<div class="eyebrow">SMART INSIGHTS · CONSISTENCY ${ins.consistency}/100</div><div class="insight-grid"><div class="insight-box"><b>${ins.acceptanceRate}%</b><small>RECENT ACCEPTANCE</small></div><div class="insight-box"><b>${esc(ins.favoriteLanguage)}</b><small>FAVOURITE LANGUAGE</small></div><div class="insight-box"><b>${ins.averagePerActiveDay}</b><small>SUBMISSIONS / ACTIVE DAY</small></div><div class="insight-box"><b>${String(ins.productiveHour).padStart(2,'0')}:00</b><small>PEAK HOUR · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone||'local')}</small></div><div class="insight-box"><b>${esc(ins.productiveWeekday)}</b><small>MOST ACTIVE DAY</small></div><div class="insight-box"><b>${ins.firstTryRate}%</b><small>FIRST-TRY ACCEPTS*</small></div></div><div class="insight-topics"><span class="muted">Focus:</span>${recs.topics.map(t=>`<a class="insight-topic" href="${esc(t.url)}" target="_blank" rel="noopener">${esc(t.name)} · ${t.solved} solved</a>`).join('')||'<span class="insight-topic">Explore new topics</span>'}</div><div class="muted" style="font-size:8px;margin-top:6px">Based on the latest 15 submissions and the activity calendar. *Approximate.</div><div class="insight-topics">${ins.milestones.filter(m=>m.date).slice(0,2).map(m=>`<span class="insight-topic">${m.total} solved ~${m.date}</span>`).join('')}</div>`;$('#duel-history').innerHTML=history.length?`<div class="eyebrow">DUEL HISTORY</div>${history.slice(0,5).map(d=>`<div class="feature-empty">${esc(d.winner||'Draw')} · ${esc(d.status)}</div>`).join('')}`:''}catch(e){box.textContent=`Insights unavailable: ${e.message}`}
 const code=`[![${u.name||u.username} on stalkmyleetcode](https://${location.host}/api/badge/${encodeURIComponent(u.username)}.svg)](https://${location.host})`;$('#badge-code').value=code;$('#badge-copy').onclick=()=>navigator.clipboard.writeText(code).then(()=>toast('<b>Badge embed copied</b>')).catch(()=>toast('Clipboard unavailable.'));setupFocus(u.username)}
function setupFocus(username){let store=readStore('stalk.focus.sessions',{}),total=store[username]||0;$('#focus-total').textContent=`${total} min logged in this browser`;focusRemaining=1500;const paint=()=>{$('#focus-display').textContent=`${String(Math.floor(focusRemaining/60)).padStart(2,'0')}:${String(focusRemaining%60).padStart(2,'0')}`};paint();$('#focus-toggle').onclick=()=>{if(focusTimer){clearInterval(focusTimer);focusTimer=null;$('#focus-toggle').textContent='Resume sprint';return}$('#focus-toggle').textContent='Pause';focusTimer=setInterval(()=>{focusRemaining--;paint();if(focusRemaining<=0){clearInterval(focusTimer);focusTimer=null;store[username]=(store[username]||0)+25;writeStore('stalk.focus.sessions',store);$('#focus-total').textContent=`${store[username]} min logged in this browser`;$('#focus-toggle').textContent='Start another sprint';pulseConfetti();toast('<b>Sprint complete!</b> Take a quick break.') }},1000)}}
function openWhatsNew(){writeStore('stalk.whatsNew.v3',true);openModal(`<div class="modal-header"><div><span class="eyebrow">WHAT’S NEW</span><h2>Level up your club</h2></div><button class="modal-close" aria-label="Close">×</button></div><div class="feature-list"><div class="feature-empty">⚔ Challenge friends in timed duels and race through crew quests.</div><div class="feature-empty">✦ Earn league points, rewind daily snapshots, and export your stats.</div><div class="feature-empty">🧠 See consistency insights, focus topics, and milestone estimates.</div><div class="feature-empty">💬 React to clears, talk in the shoutbox, and build a club playlist.</div></div><button id="whats-new-close" class="btn primary" style="width:100%;margin-top:14px">Let’s go</button>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal;$('#whats-new-close').onclick=closeModal}
function openShortcuts(){openModal(`<div class="modal-header"><div><span class="eyebrow">KEYBOARD SHORTCUTS</span><h2>Move fast</h2></div><button class="modal-close" aria-label="Close">×</button></div><div class="admin-toggle"><span>Open command palette</span><kbd>Ctrl / ⌘ + K</kbd></div><div class="admin-toggle"><span>Show shortcuts</span><kbd>?</kbd></div><div class="admin-toggle"><span>Close modal</span><kbd>Esc</kbd></div>`);$('#modal-root').querySelector('.modal-close').onclick=closeModal}
function openWrapped(){const top=[...users].sort((a,b)=>(b.week||0)-(a.week||0))[0],hard=[...users].sort((a,b)=>(b.hard||0)-(a.hard||0))[0],streak=[...users].sort((a,b)=>streakInfo(b).longest-streakInfo(a).longest)[0],cards=[['WEEKLY MVP',top?.name||'—',`${top?.week||0} submissions this week`],['HARD MODE',hard?.name||'—',`${hard?.hard||0} Hards solved`],['STREAK KEEPER',streak?.name||'—',`${streak?streakInfo(streak).longest:0} day longest streak`]];let index=0;const draw=()=>{const [label,name,sub]=cards[index];openModal(`<div class="wrapped-card"><span class="eyebrow">WEEKLY WRAPPED · ${index+1}/${cards.length}</span><h2>${esc(label)}</h2><strong>${esc(name)}</strong><p>${esc(sub)}</p><div class="wrapped-nav"><button id="wrapped-prev" class="btn small" ${index===0?'disabled':''}>←</button><button id="wrapped-download" class="btn small">Download card</button><button id="wrapped-next" class="btn small" ${index===cards.length-1?'disabled':''}>→</button></div><button class="modal-close wrapped-close" aria-label="Close">×</button></div>`);$('#wrapped-prev').onclick=()=>{index--;draw()};$('#wrapped-next').onclick=()=>{index++;draw()};$('#wrapped-download').onclick=()=>downloadWrappedCard(label,name,sub);$('#modal-root').querySelector('.wrapped-close').onclick=closeModal};draw()}
function downloadWrappedCard(title,name,sub){const c=document.createElement('canvas');c.width=1080;c.height=1350;const x=c.getContext('2d');x.fillStyle='#0B0D12';x.fillRect(0,0,1080,1350);x.fillStyle='#C6F135';x.font='700 28px sans-serif';x.fillText('stalkmyleetcode · WEEKLY WRAPPED',85,115);x.fillStyle='#E8ECF4';x.font='700 72px sans-serif';x.fillText(title,85,440);x.fillStyle='#C6F135';x.font='700 58px sans-serif';x.fillText(name.slice(0,24),85,590);x.fillStyle='#8A93A6';x.font='30px sans-serif';x.fillText(sub,85,660);c.toBlob(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stalkmyleetcode-wrapped.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)})}
async function openHelp(query){$('#help-results').textContent='Searching…';try{const rows=await api('/api/help?q='+encodeURIComponent(query));$('#help-results').innerHTML=rows.map(x=>`<div class="help-result"><a href="https://leetcode.com/problems/${encodeURIComponent(x.titleSlug)}/" target="_blank" rel="noopener">${esc(x.title)}</a><small>${esc(x.name)} · ${esc(x.lang)} · ${ago(x.timestamp)}</small></div>`).join('')||'<div class="feature-empty">No recent accepted match. Search a different title or ask the squad.</div>'}catch(e){$('#help-results').textContent=e.message}}
